// downloadHint says what the download does: an encrypted dump behind a
// signed link once a kit exists, the plain dump before. A copy of volumes
// is always made first and offered as a link.
func downloadHint(ctx context.Context, kit, volumes bool) string {
	switch {
	case volumes && kit:
		return t(ctx, "svcbackup.download_hint_volumes")
	case volumes:
		return t(ctx, "backup.hint_volumes")
	case kit:
		return t(ctx, "svcbackup.download_hint")
	}
	return t(ctx, "backup.hint")
}

